-- RiftAcademy cards + card_printings seed
-- Generated from Riftcodex snapshots per RiftCore section 6 as adjudicated 2026-08-05.
-- Run AFTER migrations 001-007. Wrapped in a transaction: all or nothing.
-- power_cost and might_bonus load NULL; the source lacks the required detail.

begin;



do $$
declare nc int; np int;
begin
  select count(*) into nc from cards;
  select count(*) into np from card_printings;
  if nc <> 905 then raise exception 'cards loaded %, expected 905', nc; end if;
  if np <> 1140 then raise exception 'card_printings loaded %, expected 1140', np; end if;
end $$;

commit;
