insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-138-166','Shen, Leader of the Kinkou Order','{"Unit"}','{"Champion"}','{"Shen","Ionia"}','{"Order"}',6,null,7,null,false,'[Shield] (+1 :rb_might: while I''m a defender.)When I hold, if there is exactly one other unit you control here, you score 1 point.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-139-166','Akali, Rogue Assassin','{"Legend"}','{}','{"Akali"}','{"Calm","Fury"}',null,null,null,null,false,'[Empower] :rb_energy_3::rb_rune_rainbow:[Action][&gt;] :rb_exhaust:: If it''s your turn, move a friendly unit in a showdown to base and if I''m [Empowered], ready it.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-140-166','Shuriken Flip','{"Spell"}','{"Signature"}','{"Akali"}','{"Calm","Fury"}',1,null,null,null,false,'Deal 2 to up to one enemy unit at a battlefield, then move a friendly unit.[Flow] :rb_energy_3::rb_rune_rainbow: (You may play this from your trash for its Flow cost. Then banish it.)');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-141-166','Renekton, Butcher of the Sands','{"Legend"}','{}','{"Renekton"}','{"Body","Fury"}',null,null,null,null,false,'[Reaction][&gt;] :rb_rune_rainbow::rb_rune_rainbow:, :rb_exhaust:: [Add] :rb_energy_2:. Spend this Energy only to play units or activated abilities of units.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-142-166','Dominus','{"Spell"}','{"Signature"}','{"Renekton"}','{"Body","Fury"}',4,null,null,null,false,'[Action] (Play on your turn or in showdowns.)This turn, double a unit''s Might and give it &quot;:rb_rune_rainbow::rb_rune_rainbow:: Ready me.&quot;');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-143-166','Zed, Master of Shadows','{"Legend"}','{}','{"Zed"}','{"Chaos","Fury"}',null,null,null,null,false,'When you banish a card you own, empower me.[Action][&gt;] Disempower me, :rb_exhaust:: Discard 1, then draw 1.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-144-166','Death Mark','{"Spell"}','{"Signature"}','{"Zed"}','{"Chaos","Fury"}',2,null,null,null,false,'[Burn 3]. (Put the top 3 cards of your Main Deck into your trash.)Play a 0 :rb_might: Shadow Clone unit token. (It has &quot;When I attack, you may banish a unit from your trash. If you do, give me [Assault 4] this turn.&quot;)[Flow] :rb_energy_1::rb_rune_rainbow::rb_rune_rainbow: (You may play this from your trash for its Flow cost. Then banish it.)');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-145-166','Nasus, Curator of the Sands','{"Legend"}','{}','{"Nasus"}','{"Calm","Mind"}',null,null,null,null,false,'When you play a unit, gear, or activated ability with Energy cost :rb_energy_7: or more, you may exhaust me to ready up to 2 runes.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-146-166','Siphoning Strike','{"Spell"}','{"Signature"}','{"Nasus"}','{"Calm","Mind"}',4,null,null,null,false,'Deal 4 to a unit at a battlefield. If you control 7 or more runes, deal 7 to it instead. When it dies this turn, channel 1 rune exhausted.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-147-166','Shen, Eye of Twilight','{"Legend"}','{}','{"Shen"}','{"Calm","Order"}',null,null,null,null,false,'[Action][&gt;] :rb_exhaust:: Give a friendly unit [Tank] this turn. (It must be assigned combat damage first.)');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-148-166','Shadow Dash','{"Spell"}','{"Signature"}','{"Shen"}','{"Calm","Order"}',2,null,null,null,false,'Move an enemy unit to a battlefield where you have units. If you have exactly two units there, they each get +1 :rb_might: this turn.[Flow] :rb_energy_5::rb_rune_rainbow::rb_rune_rainbow: (You may play this from your trash for its Flow cost. Then banish it.)');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-149-166','Jayce, Defender of Tomorrow','{"Legend"}','{}','{"Jayce"}','{"Body","Mind"}',null,null,null,null,false,'[Empower] :rb_energy_2::rb_rune_rainbow::rb_rune_rainbow: (:rb_energy_2::rb_rune_rainbow::rb_rune_rainbow:: Empower me. Use only if not Empowered.):rb_energy_1:, :rb_exhaust:: Ready a gear.[Empowered][&gt;] :rb_energy_1:, :rb_exhaust:: Ready 2 gear.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-150-166','Acceleration Gate','{"Spell"}','{"Signature"}','{"Jayce"}','{"Body","Mind"}',3,null,null,null,false,'Ready up to 4 units, gear, and/or runes.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-151-166','Mel, Soul''s Reflection','{"Legend"}','{}','{"Mel"}','{"Chaos","Mind"}',null,null,null,null,false,'When you empower something else, empower me. (I become Empowered if I''m not already.)Disempower me, :rb_exhaust:: Give a unit at a battlefield -2 :rb_might: this turn.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-152-166','Rebuttal','{"Spell"}','{"Signature"}','{"Mel"}','{"Chaos","Mind"}',1,null,null,null,false,'[Reaction] (Play any time, even before spells and abilities resolve.)Choose a spell with Energy cost no more than :rb_energy_4:.  You may pay :rb_rune_rainbow:. If you do, gain control of it and you may make new choices for it. Otherwise, counter it.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-153-166','Ambessa, Matriarch of War','{"Legend"}','{}','{"Ambessa"}','{"Body","Order"}',null,null,null,null,false,'When you empower something else, empower me. (I become Empowered if I''m not already.)Disempower me, :rb_rune_rainbow:, :rb_exhaust:: Ready a unit.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-154-166','Public Execution','{"Spell"}','{"Signature"}','{"Ambessa"}','{"Body","Order"}',2,null,null,null,false,'Choose a friendly unit. Kill an enemy unit with less Might than it.[Flow] :rb_energy_5::rb_rune_rainbow::rb_rune_rainbow: (You may play this from your trash for its Flow cost. Then banish it.)');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-155-166','Yordle, Kennen, Heart of the Tempest','{"Legend"}','{}','{"Yordle","Kennen"}','{"Chaos","Order"}',null,null,null,null,false,'When you play a card from anywhere other than your hand, empower me.[Action][&gt;] Disempower me, :rb_exhaust:: Give a unit [Assault 2] this turn. (+2 :rb_might: while it''s an attacker.)');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-156-166','Lightning Rush','{"Spell"}','{"Signature"}','{"Kennen"}','{"Chaos","Order"}',1,null,null,null,false,'Look at the top 3 cards of your Main Deck. You may choose a card from among them and draw it. Put the rest into your trash.[Flow] :rb_energy_2::rb_rune_rainbow: (You may play this from your trash for its Flow cost. Then banish it.)');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-157-166','Dragon Roost','{"Battlefield"}','{}','{}','{}',null,null,null,null,false,'Any player may pay :rb_rune_rainbow::rb_rune_rainbow: as an additional cost to play a Dragon. If they do, they play it to this battlefield.');
insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-158-166','Heisho, Shell of the World','{"Battlefield"}','{}','{}','{}',null,null,null,null,false,'Players ignore [Deflect] while paying for spells and abilities choosing something here.');
