insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-160-166','Mystic Vortex','{"Battlefield"}','{}','{}','{}',null,null,null,null,false,'During showdowns here, cards with [Reaction] cost :rb_rune_rainbow: more to play. (Hidden cards have [Reaction].)');
