insert into cards (card_code,name,card_type,supertypes,tags,domains,energy_cost,power_cost,might,might_bonus,is_token,rules_text) values ('ven-163-166','Risen Altar','{"Battlefield"}','{}','{}','{}',null,null,null,null,false,'[Empower] costs of your units here cost :rb_energy_1: or :rb_rune_rainbow: less.');
